// Despliegue de una tienda en EC2. Corrige su defecto principal.
export const despliegue = {
  region: "us-east-1",
  instancias: [
    { nombre: "web-1", zona: "us-east-1a" },
    { nombre: "web-2", zona: "us-east-1a" },
    { nombre: "web-3", zona: "us-east-1a" },
  ],
};

solution.code:
export const despliegue = {
  region: "us-east-1",
  instancias: [
    { nombre: "web-1", zona: "us-east-1a" },
    { nombre: "web-2", zona: "us-east-1b" },
    { nombre: "web-3", zona: "us-east-1a" },
  ],
};

spec.code:
for (const instancia of despliegue.instancias) {
  assert.ok(instancia.zona.startsWith(despliegue.region), instancia.nombre + " debe estar en una zona de " + despliegue.region);
}

for (const instancia of despliegue.instancias) {
  assert.ok(/^us-east-1[a-z]$/.test(instancia.zona), instancia.zona + " no es un código de zona válido");
}

