// Clasifica un código de ubicación de AWS. Corrige su defecto principal.
export type TipoUbicacion = "REGION" | "ZONA_DE_DISPONIBILIDAD" | "LOCAL_ZONE";

export function tipoDeUbicacion(codigo: string): TipoUbicacion {
  if (/\d$/.test(codigo)) {
    return "REGION";
  }
  if (/^[a-z]{2}-[a-z]+-\d[a-z]$/.test(codigo)) {
    return "ZONA_DE_DISPONIBILIDAD";
  }
  return "LOCAL_ZONE";
}

solution.code:
export type TipoUbicacion = "REGION" | "ZONA_DE_DISPONIBILIDAD" | "LOCAL_ZONE";

export function tipoDeUbicacion(codigo: string): TipoUbicacion {
  if (/^[a-z]{2}-[a-z]+-\d$/.test(codigo)) {
    return "REGION";
  }
  if (/^[a-z]{2}-[a-z]+-\d[a-z]$/.test(codigo)) {
    return "ZONA_DE_DISPONIBILIDAD";
  }
  return "LOCAL_ZONE";
}

spec.code:
const a = tipoDeUbicacion("us-west-2-lax-1");
const b = tipoDeUbicacion("us-east-1");
const c = tipoDeUbicacion("us-west-2-lax-1");
assert.deepStrictEqual([a, b, c], ["LOCAL_ZONE", "REGION", "LOCAL_ZONE"]);
